-- Gate 2 runtime exceptions (GATE2-001, F13, F31, CONTEXT_PACK §3.2 step 8, §8.2-§8.4, §8.8). Generated by
-- `pnpm db:generate --name gate2_exceptions` from src/schema/gate2.ts, then reviewed. Forward-only: never edit once
-- applied; add a new migration. Decisions are appended to the existing `gate_decisions` ledger (20261029200100).
CREATE TABLE "gate2_exceptions" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"run_id" uuid NOT NULL,
	"session_id" text NOT NULL,
	"subtask_id" uuid,
	"test_case_id" uuid,
	"tool_name" text NOT NULL,
	"proposed_action" jsonb NOT NULL,
	"envelope_reason" text NOT NULL,
	"intrusiveness" text NOT NULL,
	"batch" boolean DEFAULT false NOT NULL,
	"state" text DEFAULT 'pending' NOT NULL,
	"state_version" integer DEFAULT 0 NOT NULL,
	"requester_id" uuid,
	"plan_approver_id" uuid,
	"decided_by" uuid,
	"decided_at" timestamp with time zone,
	"timeout_at" timestamp with time zone NOT NULL,
	"idempotency_key" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "gate2_exceptions_tenant_idempotency_key" UNIQUE("tenant_id","idempotency_key"),
	CONSTRAINT "gate2_exceptions_state_check" CHECK ("gate2_exceptions"."state" IN ('pending', 'approved_once', 'denied', 'timed_out', 'superseded')),
	CONSTRAINT "gate2_exceptions_intrusiveness_check" CHECK ("gate2_exceptions"."intrusiveness" IN ('passive', 'active_safe', 'state_changing', 'destructive')),
	CONSTRAINT "gate2_exceptions_state_version_check" CHECK ("gate2_exceptions"."state_version" >= 0),
	CONSTRAINT "gate2_exceptions_tool_name_check" CHECK (length(btrim("gate2_exceptions"."tool_name")) > 0),
	CONSTRAINT "gate2_exceptions_envelope_reason_check" CHECK (length(btrim("gate2_exceptions"."envelope_reason")) > 0),
	CONSTRAINT "gate2_exceptions_session_id_check" CHECK (length(btrim("gate2_exceptions"."session_id")) > 0),
	CONSTRAINT "gate2_exceptions_idempotency_key_check" CHECK (length("gate2_exceptions"."idempotency_key") BETWEEN 1 AND 255),
	CONSTRAINT "gate2_exceptions_proposed_action_check" CHECK (jsonb_typeof("gate2_exceptions"."proposed_action") = 'object'),
	CONSTRAINT "gate2_exceptions_timeout_check" CHECK ("gate2_exceptions"."timeout_at" > "gate2_exceptions"."created_at"),
	CONSTRAINT "gate2_exceptions_decided_at_check" CHECK (("gate2_exceptions"."state" = 'pending') = ("gate2_exceptions"."decided_at" IS NULL)),
	CONSTRAINT "gate2_exceptions_decided_by_check" CHECK (("gate2_exceptions"."state" IN ('approved_once', 'denied')) = ("gate2_exceptions"."decided_by" IS NOT NULL)),
	CONSTRAINT "gate2_exceptions_sod_check" CHECK ("gate2_exceptions"."state" <> 'approved_once' OR ("gate2_exceptions"."decided_by" IS DISTINCT FROM "gate2_exceptions"."requester_id" AND "gate2_exceptions"."decided_by" IS DISTINCT FROM "gate2_exceptions"."plan_approver_id")),
	CONSTRAINT "gate2_exceptions_no_destructive_approval_check" CHECK (NOT ("gate2_exceptions"."state" = 'approved_once' AND "gate2_exceptions"."intrusiveness" = 'destructive')),
	CONSTRAINT "gate2_exceptions_approved_in_time_check" CHECK ("gate2_exceptions"."state" <> 'approved_once' OR "gate2_exceptions"."decided_at" < "gate2_exceptions"."timeout_at")
);
--> statement-breakpoint
ALTER TABLE "gate2_exceptions" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE INDEX "gate2_exceptions_tenant_run_state_idx" ON "gate2_exceptions" USING btree ("tenant_id","run_id","state");--> statement-breakpoint
CREATE POLICY "gate2_exceptions_tenant_isolation" ON "gate2_exceptions" AS PERMISSIVE FOR ALL TO public USING (tenant_id = current_setting('app.tenant_id')::uuid) WITH CHECK (tenant_id = current_setting('app.tenant_id')::uuid);
-- Hand-written below (Drizzle models neither FORCE ROW LEVEL SECURITY, grants nor triggers). Reviewed.
-- FORCE: the owner role is subject to the tenant policies too, so nothing reads across tenants.
ALTER TABLE "gate2_exceptions" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
-- Grants. Default privileges give the app role all four DML rights on new tables, so what it must not
-- have is taken back explicitly (TRUNCATE and PUBLIC too). Exceptions are updated by the state machine
-- but never deleted.
REVOKE ALL ON "gate2_exceptions" FROM PUBLIC;--> statement-breakpoint
REVOKE DELETE, TRUNCATE ON "gate2_exceptions" FROM bw_app;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON "gate2_exceptions" TO bw_app;--> statement-breakpoint
-- Keeps updated_at in step with the state changes (bw_set_updated_at: 0002_column_mixins).
CREATE TRIGGER gate2_exceptions_set_updated_at BEFORE UPDATE ON "gate2_exceptions" FOR EACH ROW EXECUTE FUNCTION bw_set_updated_at();--> statement-breakpoint
-- The state machine's last line of defence (F13, §8.2-§8.4), whoever issues the write:
--   - a row is born `pending`, undecided, at version 0;
--   - the only change is pending -> approved_once | denied | timed_out | superseded with version + 1;
--     a decided row never changes again and its identity and envelope columns never change;
--   - the decision instant is taken from the database clock, never backdated or in the future;
--   - a timeout cannot fire early, and an approval cannot land at or after the timeout (silence is a denial);
--   - approval needs a decider who is neither the requester nor the plan approver (SoD, §8.4) and is never
--     allowed for a destructive exception (§8.3). The CHECK constraints repeat the last two, so they hold
--     even if this trigger is ever disabled; the explicit messages here are for the caller.
CREATE FUNCTION bw_gate2_exceptions_guard() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.state <> 'pending' OR NEW.state_version <> 0 OR NEW.decided_by IS NOT NULL OR NEW.decided_at IS NOT NULL THEN
      RAISE EXCEPTION 'gate2 exception must be created pending, undecided, at version 0'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.state <> 'pending' THEN
    RAISE EXCEPTION 'gate2 exception is already % and cannot change', OLD.state
      USING ERRCODE = 'restrict_violation';
  END IF;
  -- A move to another tenant is the same denial RLS gives (insufficient_privilege, 42501).
  IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id THEN
    RAISE EXCEPTION 'gate2 exception cannot move to another tenant'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.run_id IS DISTINCT FROM OLD.run_id
     OR NEW.session_id IS DISTINCT FROM OLD.session_id
     OR NEW.subtask_id IS DISTINCT FROM OLD.subtask_id
     OR NEW.test_case_id IS DISTINCT FROM OLD.test_case_id
     OR NEW.tool_name IS DISTINCT FROM OLD.tool_name
     OR NEW.proposed_action IS DISTINCT FROM OLD.proposed_action
     OR NEW.envelope_reason IS DISTINCT FROM OLD.envelope_reason
     OR NEW.intrusiveness IS DISTINCT FROM OLD.intrusiveness
     OR NEW.batch IS DISTINCT FROM OLD.batch
     OR NEW.requester_id IS DISTINCT FROM OLD.requester_id
     OR NEW.plan_approver_id IS DISTINCT FROM OLD.plan_approver_id
     OR NEW.timeout_at IS DISTINCT FROM OLD.timeout_at
     OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'gate2 exception identity and envelope columns are immutable'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.state = 'pending' THEN
    RAISE EXCEPTION 'gate2 exception can only move out of pending'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.state_version IS DISTINCT FROM OLD.state_version + 1 THEN
    RAISE EXCEPTION 'gate2 exception state_version must advance by exactly one'
      USING ERRCODE = 'serialization_failure';
  END IF;
  IF NEW.decided_at IS NULL OR NEW.decided_at < pg_catalog.now() OR NEW.decided_at > pg_catalog.clock_timestamp() THEN
    RAISE EXCEPTION 'gate2 decision instant must come from the database clock'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.state = 'approved_once' THEN
    IF NEW.intrusiveness = 'destructive' THEN
      RAISE EXCEPTION 'a destructive gate2 exception can never be approved'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.decided_by IS NULL
       OR NEW.decided_by IS NOT DISTINCT FROM NEW.requester_id
       OR NEW.decided_by IS NOT DISTINCT FROM NEW.plan_approver_id THEN
      RAISE EXCEPTION 'gate2 approval violates separation of duties: the approver must differ from the requester and the plan approver'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.decided_at >= NEW.timeout_at THEN
      RAISE EXCEPTION 'gate2 approval arrived at or after the timeout: denied by default'
        USING ERRCODE = 'check_violation';
    END IF;
  ELSIF NEW.state = 'timed_out' AND NEW.decided_at < NEW.timeout_at THEN
    RAISE EXCEPTION 'gate2 timeout cannot be recorded before timeout_at'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;--> statement-breakpoint
CREATE TRIGGER gate2_exceptions_guard BEFORE INSERT OR UPDATE ON "gate2_exceptions" FOR EACH ROW EXECUTE FUNCTION bw_gate2_exceptions_guard();--> statement-breakpoint
-- Every terminal transition has exactly one matching gate_decisions row (gate 2, keyed `gate2:<id>`, the
-- approve/deny outcome, the same actor, auto for a timeout or supersede), checked at commit so the two writes
-- may come in either order inside the transaction. Uniqueness of the row is gate_decisions' tenant dedupe key.
CREATE FUNCTION bw_gate2_exceptions_decision_check() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.gate_decisions d
     WHERE d.tenant_id = NEW.tenant_id
       AND d.gate = 2
       AND d.dedupe_key = 'gate2:' || NEW.id::text
       AND d.run_id = NEW.run_id
       AND d.status = CASE WHEN NEW.state = 'approved_once' THEN 'approved' ELSE 'denied' END
       AND d.decided_by IS NOT DISTINCT FROM NEW.decided_by
       AND d.auto = (NEW.decided_by IS NULL)
  ) THEN
    RAISE EXCEPTION 'gate2 exception % reached % without a matching gate_decisions row', NEW.id, NEW.state
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END
$$;--> statement-breakpoint
CREATE CONSTRAINT TRIGGER gate2_exceptions_decision_check AFTER UPDATE ON "gate2_exceptions" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN (NEW.state <> 'pending') EXECUTE FUNCTION bw_gate2_exceptions_decision_check();
